import {dateKey,parseDate,addDays,monday,isoWeek,monthCells,eventOnDate,formatDate,pad,toICS} from './calendar.js';
import * as Google from './google.js';
import {chooseRecovery,readMirror,writeMirror} from './storage.js';

const KEY='unbound-days-v1', HISTORY=KEY+'-history';
const TODAY=dateKey(new Date()),months=Array.from({length:12},(_,i)=>new Date(2026,i,1).toLocaleDateString('en-GB',{month:'long'}));
const coverNames=['Cognac leather','Forest leather','Kintsugi','Stained glass','Pressed botanicals','Retro futurism','Topographic relief','Mother of pearl','Embroidered tapestry','Liquid chrome','Navy linen','Ivory leather','Burgundy leather','Ocean suede','Terracotta linen','Walnut wood','Art Deco','Watercolour landscape','Celestial','Botanical linen','Saddle stitched leather','Oxblood tooled leather','Midnight leather','Ivory quilted leather','Heritage leather','Steampunk brass','Rococo gilded sage','Brushed titanium','Indigo sashiko','Wood marquetry','Moonstone silver','Plum velvet'];
const coverFiles=['leather-saddle','leather-oxblood','leather-black','leather-ivory','leather-vintage','steampunk','rococo','titanium','japanese','marquetry','moonstone','velvet'];
const lightCovers=[4,5,6,7,9,11,17,19,23,26,30];
const emptyState=()=>({version:1,events:[],tasks:[],notes:[],habits:[],entries:{},ink:{},trash:[],settings:{cover:0,owner:'',title:'',font:'Caveat',ink:'#313a41',googleClientId:'',selectedCalendars:[],defaultCalendar:'primary',favorites:[],coverPosition:50,coverInk:''},cachedGoogle:[],googleCalendars:[]});
let state=emptyState(),storageError=false,storageCorrupt=false,externalChange=false,mirrorQueue=Promise.resolve(),cloudTimer,cloudBusy=false,cloudDirty=false,lastCloud=0,cloudStatus='Not connected',saveGeneration=0;
let deviceId;try{deviceId=localStorage.getItem(KEY+'-device')||crypto.randomUUID();localStorage.setItem(KEY+'-device',deviceId);}catch{deviceId=crypto.randomUUID();}
try{const saved=localStorage.getItem(KEY);if(saved){const data=JSON.parse(saved);if(data.version!==1||!Array.isArray(data.events))throw Error('Invalid saved data');state={...state,...data,settings:{...state.settings,...data.settings}};}}catch{storageError=true;storageCorrupt=true;}
try{const recovery=await readMirror();const chosen=chooseRecovery(storageCorrupt?null:state,recovery);if(chosen){state={...emptyState(),...chosen,settings:{...emptyState().settings,...chosen.settings}};if(storageCorrupt){storageCorrupt=false;storageError=false;localStorage.setItem(KEY,JSON.stringify(state));}}}catch{}
let date=TODAY,section='calendar',view='week',closed=true,noteId=state.notes[0]?.id||null,focusField=null,speech=null,lastSnapshot=0,previousView='',googleBusy=false,onlyFavorites=false;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const entry=k=>state.entries[k]||'';
const year=()=>parseDate(date).getFullYear();
const month=()=>parseDate(date).getMonth();
const setEntry=(k,v)=>{state.entries[k]=v;save();};
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000);}
function snapshot(){try{const records=JSON.parse(localStorage.getItem(HISTORY)||'[]');records.unshift({time:new Date().toISOString(),data:state});localStorage.setItem(HISTORY,JSON.stringify(records.slice(0,5)));lastSnapshot=Date.now();}catch{}}
function save(){
  if(storageCorrupt||externalChange){storageError=true;document.querySelector('#save-status').textContent='Changes need recovery';toast(externalChange?'Another tab changed this notebook. Export any unsaved writing, then reload.':'Saved data needs recovery. Restore a backup before saving.');return;}
  state.savedAt=new Date().toISOString();const data=structuredClone(state),generation=++saveGeneration;let localOK=false;
  try{localStorage.setItem(KEY,JSON.stringify(data));storageError=false;localOK=true;if(Date.now()-lastSnapshot>300000)snapshot();}catch{storageError=true;}
  document.querySelector('#save-status').textContent=localOK?'Saved on this device':'Saving recovery copy…';
  mirrorQueue=mirrorQueue.catch(()=>{}).then(()=>writeMirror(data)).then(()=>{if(generation===saveGeneration){storageError=false;document.querySelector('#save-status').textContent=Google.backupConnected()?'Saved · Google backup pending':'Saved on this device';}}).catch(()=>{if(!localOK&&generation===saveGeneration){storageError=true;document.querySelector('#save-status').textContent='Not saved — export a backup';toast('Storage unavailable. Export your notebook now.');}});
  cloudDirty=true;queueCloudBackup();
}
function queueCloudBackup(){if(!Google.backupConnected()||cloudTimer||cloudBusy)return;cloudTimer=setTimeout(()=>{cloudTimer=null;runCloudBackup().catch(()=>{});},Math.max(5000,60000-(Date.now()-lastCloud)));}
async function runCloudBackup(force=false){
  if(cloudBusy)return;if(!Google.backupConnected())throw Error('Reconnect Google with notebook backup enabled.');if(!cloudDirty&&!force)return;
  clearTimeout(cloudTimer);cloudTimer=null;cloudBusy=true;cloudStatus='Backing up…';const generation=saveGeneration,copy=structuredClone(state);
  try{await Google.backupNotebook(copy,deviceId);lastCloud=Date.now();cloudDirty=generation!==saveGeneration;cloudStatus='Backed up '+new Date(lastCloud).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});document.querySelector('#save-status').textContent=cloudDirty?'Saved · Google backup pending':'Saved · backed up to Google';}
  catch(e){cloudStatus=e.message;document.querySelector('#save-status').textContent='Saved locally · backup needs attention';throw e;}
  finally{cloudBusy=false;if(cloudDirty&&Google.backupConnected())queueCloudBackup();}
}
async function cloudCopies(){const copies=await Google.listBackups();openModal('Google notebook backups',`<p>Each copy is a complete notebook. Restoring is explicit; other devices never overwrite your notebook automatically.</p><div class="backup-list">${copies.map(c=>`<button data-cloud-copy="${esc(c.id)}">${esc(new Date(c.createdTime).toLocaleString())}</button>`).join('')||'<p>No Google backups yet.</p>'}</div>`);}
function openModal(title,body){document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){if(speech)speech.stop();modal.close();}
function coverStyle(c=state.settings.cover){if(c==='custom')return `background-image:url('${state.settings.customCover}');background-size:cover;background-position:${state.settings.coverPosition??50}% center;`;if(Number(c)>=20)return `background-image:url('assets/${coverFiles[Number(c)-20]}.webp');background-size:100% 100%;background-position:center;`;const index=Number(c)%10;return `${Number(c)>=10?"--atlas:url('assets/cover-atlas-classic-realistic-v2.webp');background-image:url('assets/cover-atlas-classic-realistic-v2.webp');":''}--cover-position:${index%2?100:0}% ${Math.floor(index/2)*25}%;`;}
function coverMaterial(c=state.settings.cover){const n=Number(c);if([0,1,11,12,20,21,22,23,24,25,26].includes(n))return 'leather';if([5,8,10,13,14,19,28,31].includes(n))return 'cloth';if([16,18].includes(n))return 'foil';if([3,4,7,9,27,30].includes(n))return 'gloss';if([2,6,15,29].includes(n))return 'relief';return 'printed';}
function applyTheme(){document.documentElement.style.setProperty('--ink',state.settings.ink);document.documentElement.style.setProperty('--hand',`'${state.settings.font}', 'Segoe Print', 'Bradley Hand', cursive`);}
function render(){applyTheme();if(closed){previousView='';renderCover();return;}const navigationKey=section+':'+view+':'+date+':'+(section==='notes'?noteId:'');const turn=previousView&&previousView!==navigationKey;const oldDate=previousView.split(':')[2];const backwards=oldDate&&date<oldDate;const departing=turn?document.querySelector('.book')?.cloneNode(true):null;const titles={calendar:view==='year'?`${year()} at a glance`:view==='month'?`${months[month()]} ${year()}`:view==='week'?`${formatDate(monday(date),{day:'numeric',month:'short'})} — ${formatDate(addDays(monday(date),6),{day:'numeric',month:'short',year:'numeric'})}`:formatDate(date,{weekday:'long',day:'numeric',month:'long'}),goals:`Goals for ${year()}`,tasks:'Things to do',notes:'Notes & ideas',habits:`${months[month()]} habits`,reflection:`${months[month()]} reflection`};
const tabNames={calendar:'Calendar',goals:'Goals',tasks:'To do',notes:'Notes',habits:'Habits',reflection:'Reflection'};
app.innerHTML=`<div class="book-shell"><nav class="section-tabs" aria-label="Notebook sections">${Object.entries(tabNames).map(([k,v])=>`<button class="section-tab ${section===k?'active':''}" data-section="${k}" aria-current="${section===k?'page':'false'}">${v}</button>`).join('')}</nav><button class="bookmark-today" data-action="today" title="Go to today" aria-label="Go to today">TODAY</button><div class="book ${turn?'turning':''}"><div class="book-head"><div><div class="eyebrow">${section==='calendar'&&view==='week'?`Week ${isoWeek(date).week} · `:''}Unbound Days</div><h1>${titles[section]}</h1></div><div class="date-controls"><button class="round-button" data-action="prev" aria-label="Previous ${view}">‹</button><select id="year-select" aria-label="Planner year">${Array.from({length:21},(_,i)=>year()-10+i).map(y=>`<option ${y===year()?'selected':''}>${y}</option>`).join('')}</select><button class="round-button" data-action="next" aria-label="Next ${view}">›</button><button class="today-button" data-action="today">Today</button>${section==='calendar'?'<button class="primary" data-action="add-event">+ Event</button>':''}</div></div>${renderSection()}<footer class="page-footer"><span>${storageError?'Not saved · please export a backup':'Your notebook · saved on this device'}</span>${section==='calendar'?`<div class="view-switch" aria-label="Calendar view">${['year','month','week','day'].map(v=>`<button data-view="${v}" class="${v===view?'active':''}" aria-pressed="${v===view}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>`:'<span>Unbound Days · First edition</span>'}</footer></div><nav class="month-tabs" aria-label="Months">${months.map((m,i)=>`<button class="month-tab ${i===month()?'active':''}" data-month="${i}" aria-label="${m}">${m.slice(0,3).toUpperCase()}</button>`).join('')}</nav></div>`;previousView=navigationKey;
if(departing&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const book=document.querySelector('.book');const leaf=document.createElement('div');leaf.className='turn-leaf'+(backwards?' backwards':'');leaf.inert=true;leaf.setAttribute('aria-hidden','true');departing.className='departing-page';departing.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));leaf.append(departing);book.append(leaf);setTimeout(()=>leaf.remove(),850);}

if(section==='notes')setupInk();
}
function renderCover(){const c=state.settings.cover;app.innerHTML=`<div class="cover-scene"><div class="cover-controls"><button class="quiet-button" data-action="gallery">Choose cover</button><button class="quiet-button" data-action="personalize">Personalise</button></div><div data-material="${coverMaterial()}" class="cover-book ${lightCovers.includes(Number(c))||c==='custom'?'light':''}" ${state.settings.coverInk?`style="--cover-ink:${state.settings.coverInk}"`:''}><div class="cover-art" style="${coverStyle()}"></div><div class="page-block" aria-hidden="true"></div><div class="cover-light" aria-hidden="true"></div><div class="spine"></div><button class="cover-open" data-action="open" aria-label="Open ${year()} planner"><span class="cover-year">${year()}</span>${state.settings.title?`<span class="cover-title">${esc(state.settings.title)}</span>`:''}${state.settings.owner?`<span class="cover-owner">${esc(state.settings.owner)}</span>`:''}<span class="emboss-logo"><span class="brand-symbol">u</span>unbound days</span></button><button class="cover-tab" data-section="calendar">Calendar</button><button class="cover-tab" data-section="goals">Goals</button><button class="cover-tab" data-section="notes">Notes</button><button class="ribbon" data-action="today" aria-label="Open today"></button></div><div class="cover-hint">Your days, between these pages. <button data-action="open">Tap to open</button></div></div>`;}
function eventsFor(d){return [...state.events,...state.cachedGoogle.filter(e=>state.settings.selectedCalendars.includes(e.google.calendar))].filter(e=>eventOnDate(e,d)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));}
function ruled(key,placeholder='Write here…',extra=''){return `<textarea class="ruled" data-entry="${esc(key)}" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" ${extra}>${esc(entry(key))}</textarea>`;}
function tools(){return `<div class="write-tools"><button data-action="pencil" title="Write with Apple Pencil using iPad Scribble">✎ Pencil</button><button data-action="dictate">● Dictate</button></div>`;}
function tasksFor(d){return state.tasks.filter(t=>t.date===d&&!t.deleted);}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" data-task-check="${t.id}" aria-label="Complete ${esc(t.title)}" ${t.done?'checked':''}><button class="task-name" data-edit-task="${t.id}">${esc(t.title)}</button>${t.date?`<span class="task-meta">${formatDate(t.date,{day:'numeric',month:'short'})}</span>`:''}<button class="move-task" data-move-task="${t.id}" aria-label="Reschedule ${esc(t.title)}" title="Move to another date">↗</button></div>`;}
function miniMonth(y,m){return `<div class="mini-month"><h2><button data-month="${m}">${months[m]}</button></h2><table><thead><tr>${['M','T','W','T','F','S','S'].map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,w)=>`<tr>${monthCells(y,m).slice(w*7,w*7+7).map(d=>`<td>${parseDate(d).getMonth()===m?`<button data-date="${d}" class="${d===TODAY?'today':''} ${eventsFor(d).length?'has-event':''}" aria-label="${formatDate(d,{day:'numeric',month:'long'})}">${parseDate(d).getDate()}</button>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderSection(){if(section==='calendar'){if(view==='year')return `<div class="year-layout"><div class="year-grid">${months.map((_,m)=>miniMonth(year(),m)).join('')}</div><aside><section class="side-section"><h2>Remember</h2>${ruled(`year:${year()}:remember`,'Things to remember')}</section><section class="side-section"><h2>Year priorities</h2>${ruled(`year:${year()}:priorities`,'What matters this year')}</section></aside></div>`;if(view==='month')return renderMonth();if(view==='week')return renderWeek();return renderDay();}
if(section==='tasks'){const overdue=state.tasks.filter(t=>t.date&&t.date<TODAY&&!t.done);return `${overdue.length?`<div class="info-box">${overdue.length} unfinished task${overdue.length>1?'s':''} from earlier days. <button class="text-action" data-action="carry-tasks">Move all to today</button></div>`:''}<div style="display:flex;justify-content:space-between;margin-bottom:20px"><span class="scratch-note">Plans can change. Your tasks can, too.</span><button class="primary" data-action="add-task">+ Task</button></div><div class="task-board">${[['urgent','Most important'],['important','Important'],['time','If I have time'],['later','Sometime later']].map(([p,name])=>`<section class="task-group"><h2>${name}</h2>${state.tasks.filter(t=>t.priority===p).map(taskRow).join('')||'<p class="empty-note">A little breathing room.</p>'}</section>`).join('')}</div>`;}
if(section==='goals')return `<div style="display:flex;justify-content:flex-end;margin-bottom:12px">${tools()}</div><section class="side-section"><h2>The bigger picture</h2>${ruled(`goals:${year()}:year`,'Your goals for the year','style="min-height:100px;height:100px"')}</section><div class="goals-grid">${months.map((m,i)=>`<section class="goal-box"><h2>${m}</h2>${ruled(`goals:${year()}:${i}`,`Goals for ${m}`)}<div class="goal-actions"><button class="text-action" data-goal-task="${i}">Make a task from this goal</button></div></section>`).join('')}</div>`;
if(section==='notes')return renderNotes();
if(section==='habits'){const count=new Date(year(),month()+1,0).getDate(),prefix=`${year()}-${pad(month()+1)}`;return `<div style="display:flex;justify-content:space-between;margin-bottom:20px"><span class="scratch-note">Small things, done often.</span><button class="primary" data-action="add-habit">+ Habit</button></div><div class="habits-overflow"><table class="habits-table"><thead><tr><th>Your habit</th>${Array.from({length:count},(_,d)=>`<th>${d+1}</th>`).join('')}</tr></thead><tbody>${state.habits.map(h=>`<tr><td><button class="habit-name" data-edit-habit="${h.id}">${esc(h.title)}</button><div class="habit-progress">${Array.from({length:count},(_,d)=>`${prefix}-${pad(d+1)}`).filter(d=>h.checks.includes(d)).length} / ${count} days</div></td>${Array.from({length:count},(_,d)=>{const k=`${prefix}-${pad(d+1)}`,checked=h.checks.includes(k);return `<td><button class="habit-check ${checked?'checked':''}" data-habit="${h.id}" data-habit-date="${k}" aria-label="${esc(h.title)} on ${k}" aria-pressed="${checked}">${checked?'✓':''}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${!state.habits.length?'<p class="empty-note">Choose a habit you want to make room for.</p>':''}<section class="side-section" style="margin-top:28px"><h2>Notes</h2>${ruled(`habits:${prefix}:notes`,'Habit notes')}</section>`;}
return `<div style="display:flex;justify-content:flex-end;margin-bottom:15px">${tools()}</div><div class="reflection-grid">${[['personal','Personal goals'],['work','Work & study goals'],['well','What went well?'],['improve','What could I improve?'],['learn','What did I learn?'],['grateful','What am I grateful for?']].map(([k,t])=>`<section><h2>${t}</h2>${ruled(`reflection:${year()}:${month()}:${k}`,t)}</section>`).join('')}</div>`;}
function renderMonth(){const cells=monthCells(year(),month());return `<div class="calendar-layout"><table class="calendar-table"><thead><tr><th class="week-number"></th>${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<th>${d.slice(0,3).toUpperCase()}</th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,w)=>`<tr><td class="week-number"><button data-week="${cells[w*7]}" aria-label="Open week ${isoWeek(cells[w*7]).week}">${isoWeek(cells[w*7]).week}</button></td>${cells.slice(w*7,w*7+7).map(d=>{const e=eventsFor(d),t=tasksFor(d).filter(t=>!t.done),outside=parseDate(d).getMonth()!==month();return `<td><div class="day-cell ${outside?'outside':''} ${d===TODAY?'is-today':''}" data-day-cell="${d}" role="button" tabindex="0" aria-label="Open ${formatDate(d,{day:'numeric',month:'long'})}"><span class="day-number"><span>${parseDate(d).getDate()}</span></span>${e.slice(0,2).map(e=>`<button class="entry-chip ${e.category}" data-edit-event="${e.id}">${e.time?e.time+' ':''}${esc(e.title)}</button>`).join('')}${t.slice(0,1).map(t=>`<button class="entry-chip task" data-edit-task="${t.id}">□ ${esc(t.title)}</button>`).join('')}${e.length+t.length>3?`<span class="more-count">+${e.length+t.length-3} more</span>`:''}</div></td>`;}).join('')}</tr>`).join('')}</tbody></table><aside class="calendar-sidebar"><section class="side-section"><h2>Monthly priorities</h2>${ruled(`month:${year()}:${month()}:priorities`,'This month, make room for…')}</section><section class="side-section"><h2>Notes</h2>${ruled(`month:${year()}:${month()}:notes`,'Things to remember')}</section><div class="sync-status">${Google.connected()?'Google Calendar connected':'Google Calendar · '+(state.settings.googleClientId?'Reconnect in Settings':'set up in Settings')}</div></aside></div>`;}
function renderWeek(){const start=monday(date),days=Array.from({length:7},(_,i)=>addDays(start,i));const ordering=[0,3,1,4,2,5,6];return `<div style="display:flex;justify-content:flex-end;margin-bottom:15px">${tools()}</div><div class="weekly-grid">${ordering.map(i=>{const d=days[i],events=eventsFor(d);return `<section class="week-day"><div class="week-day-title ${d===TODAY?'is-today':''}"><button data-date="${d}">${formatDate(d,{weekday:'long'})}</button><span class="day-count">${parseDate(d).getDate()} ${parseDate(d).getMonth()!==month()?months[parseDate(d).getMonth()].slice(0,3):''}</span></div>${events.map(e=>`<button class="entry-chip ${e.category}" data-edit-event="${e.id}" style="text-align:left;font-size:23px">${e.time?e.time+' · ':''}${esc(e.title)}</button>`).join('')}${tasksFor(d).map(taskRow).join('')}${ruled(`day:${d}:notes`,`Notes for ${formatDate(d,{weekday:'long',day:'numeric',month:'short'})}`)}</section>`;}).join('')}<section class="week-day week-notes"><h2 class="small-heading">This week</h2>${ruled(`week:${start}:notes`,'A thought for the week')}</section></div>`;}
function renderDay(){const events=eventsFor(date);return `<div class="day-spread"><div><section class="priorities"><h2 class="small-heading">Today's three priorities</h2>${[1,2,3].map(n=>`<label class="priority-input"><span>${n}</span><input type="text" data-entry="day:${date}:priority:${n}" aria-label="Priority ${n}" value="${esc(entry(`day:${date}:priority:${n}`))}"></label>`).join('')}</section><section><h2 class="small-heading">On the agenda</h2>${events.map(e=>`<div class="agenda-item"><span class="agenda-time">${e.time||'All day'}</span><div><button data-edit-event="${e.id}">${esc(e.title)}</button>${e.location?`<div class="agenda-meta">${esc(e.location)}</div>`:''}</div></div>`).join('')||'<div class="empty-note">A day with room to breathe.</div>'}<button class="text-action" data-action="add-event">Add an appointment</button></section></div><div><section class="side-section"><div style="display:flex;justify-content:space-between;align-items:start"><h2>Things to do</h2><button class="text-action" data-action="add-task">+ Task</button></div>${tasksFor(date).map(taskRow).join('')||'<div class="empty-note">What would you like to get done?</div>'}</section><section class="side-section"><div style="display:flex;justify-content:space-between"><h2>Notes</h2>${tools()}</div>${ruled(`day:${date}:notes`,'Notes for today','style="min-height:240px"')}</section></div></div>`;}
function renderNotes(){const n=state.notes.find(n=>n.id===noteId);return `<div class="notes-layout"><aside><button class="primary" data-action="add-note" style="width:100%;margin-bottom:16px">+ New page</button><div class="note-list">${state.notes.map(n=>`<button class="${n.id===noteId?'active':''}" data-note="${n.id}">${esc(n.title||'Untitled page')}</button>`).join('')}</div></aside><section class="note-editor">${n?`<input type="text" data-note-title="${n.id}" aria-label="Note title" placeholder="Give this page a title" value="${esc(n.title)}"><div class="note-controls">${tools()}<button class="text-action danger" data-delete-note="${n.id}">Delete page</button></div>${ruled(`note:${n.id}`,'Your thoughts, in your own words')}<details><summary class="scratch-note">Sketch & original handwriting</summary><p class="scratch-note">Pen strokes stay as ink. For text in the handwriting font, use Scribble in the writing area above.</p><div class="ink-toolbar"><button data-ink-tool="pen" class="active">Pen</button><button data-ink-tool="eraser">Eraser</button><button data-action="undo-ink">Undo</button><button data-action="clear-ink">Clear ink</button></div><canvas class="ink-canvas" id="ink-canvas" aria-label="Handwriting and sketch area"></canvas></details>`:'<p class="empty-note">A fresh page for whatever comes to mind.</p>'}</section></div>`;}

function eventForm(eventId=null){const e=[...state.events,...state.cachedGoogle].find(e=>e.id===eventId)||{date,time:'',endTime:'',title:'',category:'personal',repeat:'none',notes:'',location:'',reminder:''};const linked=!!e.google;const calendarOptions=state.googleCalendars.filter(c=>['owner','writer'].includes(c.accessRole));openModal(eventId?'Appointment':'New appointment',`<form id="event-form" data-id="${esc(eventId||'')}">${linked?`<div class="info-box">Google Calendar event${e.google.recurring?' · edits apply to this occurrence only':''}. ${!Google.connected()?'Reconnect in Settings before saving changes.':''}</div>`:''}<div class="form-grid"><label class="wide">Appointment<input name="title" type="text" required maxlength="200" value="${esc(e.title)}" autofocus></label><label>Date<input name="date" type="date" required value="${e.date}"></label><label>End date<input name="endDate" type="date" required value="${e.endDate||e.lastDate||e.date}"></label><label>Start time · blank for all day<input name="time" type="time" value="${e.time||''}"></label><label>End time<input name="endTime" type="time" value="${e.endTime||''}"></label><label>Category<select name="category">${['personal','work','family'].map(c=>`<option ${e.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Repeat<select name="repeat" ${linked?'disabled':''}>${['none','daily','weekly','monthly','yearly'].map(c=>`<option ${e.repeat===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Reminder<select name="reminder">${[['','Default / none'],['0','At the time'],['10','10 minutes before'],['30','30 minutes before'],['60','1 hour before'],['1440','1 day before']].map(([v,t])=>`<option value="${v}" ${String(e.reminder)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Save to<select name="destination" ${linked?'disabled':''}><option value="local">This notebook</option>${calendarOptions.map(c=>`<option value="${esc(c.id)}" ${(e.google?.calendar===c.id||!eventId&&Google.connected()&&state.settings.defaultCalendar===c.id)?'selected':''}>Google · ${esc(c.summary)}</option>`).join('')}</select></label><label class="wide">Location<input name="location" type="text" value="${esc(e.location)}" maxlength="200"></label><label class="wide">Notes<textarea name="notes">${esc(e.notes)}</textarea></label></div><p class="scratch-note">Notebook reminders appear while the planner is open. Google events use Google Calendar reminders. Local repeating-event edits affect the whole series.</p><div id="form-error" class="error-text" role="alert"></div><div class="modal-footer">${eventId?`<button type="button" class="secondary danger" data-delete-event="${esc(eventId)}">Delete</button>`:''}${tools()}<button type="button" class="secondary" data-action="close-modal">Cancel</button><button type="submit" class="primary">Save appointment</button></div></form>`);}
function taskForm(taskId=null,prefill=''){const t=state.tasks.find(t=>t.id===taskId)||{title:prefill,date,priority:'important',notes:'',goal:''};openModal(taskId?'Edit task':'New task',`<form id="task-form" data-id="${taskId||''}"><div class="form-grid"><label class="wide">Task<input type="text" name="title" value="${esc(t.title)}" required maxlength="200" autofocus></label><label>Date · optional<input type="date" name="date" value="${t.date||''}"></label><label>Priority<select name="priority">${[['urgent','Most important'],['important','Important'],['time','If I have time'],['later','Sometime later']].map(([v,l])=>`<option value="${v}" ${t.priority===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="wide">Linked goal<input type="text" name="goal" value="${esc(t.goal)}" placeholder="Optional monthly milestone"></label><label class="wide">Notes<textarea name="notes">${esc(t.notes)}</textarea></label></div><div class="modal-footer">${taskId?`<button type="button" class="secondary danger" data-delete-task="${taskId}">Delete</button>`:''}${tools()}<button class="primary" type="submit">Save task</button></div></form>`);}
function gallery(){openModal('Your cover collection',`<div class="gallery-toolbar"><button class="secondary" data-action="upload-cover">Upload your own</button><label class="check-label"><input id="favorites-only" type="checkbox" ${onlyFavorites?'checked':''}> Favourites</label></div><div class="cover-grid">${coverNames.map((name,i)=>({name,i})).filter(({i})=>!onlyFavorites||state.settings.favorites.includes(i)).map(({name,i})=>`<div class="cover-choice ${state.settings.cover===i?'selected':''}"><button style="padding:0;width:100%;text-align:left" data-cover="${i}" aria-label="Choose ${name}"><span class="swatch" data-material="${coverMaterial(i)}" style="${coverStyle(i)}"></span><strong>${name}</strong><small>${state.settings.cover===i?'Your current cover':'Choose cover'}</small></button><button class="fav" data-fav="${i}" aria-label="Favourite ${name}" aria-pressed="${state.settings.favorites.includes(i)}">${state.settings.favorites.includes(i)?'♥':'♡'}</button></div>`).join('')}${state.settings.customCover?`<div class="cover-choice ${state.settings.cover==='custom'?'selected':''}"><button style="padding:0;width:100%;text-align:left" data-cover="custom"><span class="swatch" style="${coverStyle('custom')}"></span><strong>Your own cover</strong></button></div>`:''}</div><p class="cover-atlas-note">A different cover. The same notebook.</p>`);}
function personalize(){openModal('Make it yours',`<form id="personalize-form"><div class="form-grid"><label class="wide">Your name · optional<input name="owner" type="text" value="${esc(state.settings.owner)}" maxlength="80"></label><label class="wide">Cover title · optional<input name="title" type="text" value="${esc(state.settings.title)}" maxlength="80" placeholder="Just the year looks beautiful, too"></label><label>Lettering colour<select name="coverInk"><option value="">Match the cover</option><option value="#e4c18c" ${state.settings.coverInk==='#e4c18c'?'selected':''}>Warm gold</option><option value="#fff9ec" ${state.settings.coverInk==='#fff9ec'?'selected':''}>Ivory</option><option value="#273238" ${state.settings.coverInk==='#273238'?'selected':''}>Charcoal</option></select></label><label>Ink colour<select name="ink">${[['#313a41','Charcoal'],['#263f66','Blue ink'],['#763b43','Burgundy'],['#3f6548','Forest green']].map(([v,n])=>`<option value="${v}" ${state.settings.ink===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="modal-footer"><button type="submit" class="primary">Save preferences</button></div></form>`);}
function settings(){openModal('Your notebook settings',`<section class="settings-section"><h3>Writing</h3><p>Type with a keyboard, use Apple Pencil Scribble in any text field, or dictate. All text uses the same handwriting font.</p><div class="writing-tip">On iPad: enable Settings → Apple Pencil → Scribble. For dictation, use the microphone on the iPad keyboard, or the Dictate button where supported.</div><button class="text-action" data-action="personalize">Personalise cover & ink</button></section><section class="settings-section"><h3>Google Calendar</h3><p>${Google.connected()?'Connected for this session. Your access token is never saved to device storage.':'Connect to show and edit Google events in your notebook. A Google OAuth client ID is required for this installation.'}</p><label class="scratch-note" for="google-client">Google OAuth client ID</label><input type="text" id="google-client" value="${esc(state.settings.googleClientId)}" placeholder="…apps.googleusercontent.com" autocomplete="off"><label class="check-label"><input type="checkbox" id="google-backup" checked> Automatically back up my whole notebook to my Google account</label><p class="scratch-note">Includes notes, tasks, goals, ink and your chosen cover. Uses this app’s private Google Drive data folder; it cannot read your other Drive files.</p><div style="display:flex;gap:10px;margin:12px 0;flex-wrap:wrap"><button class="primary" data-action="google-connect" ${googleBusy?'disabled':''}>${Google.connected()?'Reconnect':'Connect Google Calendar'}</button><button class="secondary" data-action="google-refresh" ${!Google.connected()||googleBusy?'disabled':''}>Refresh events</button>${Google.connected()?'<button class="text-action" data-action="google-disconnect">Disconnect & clear cached events</button>':''}</div><div id="google-error" class="error-text" role="alert"></div>${state.googleCalendars.length?`<div>${state.googleCalendars.map(c=>`<div class="calendar-option"><label><input type="checkbox" data-calendar-toggle="${esc(c.id)}" ${state.settings.selectedCalendars.includes(c.id)?'checked':''}>${esc(c.summary)}</label><small>${c.accessRole==='reader'?'Read only':''}</small></div>`).join('')}</div><label class="check-label">Default calendar <select id="default-calendar">${state.googleCalendars.filter(c=>['owner','writer'].includes(c.accessRole)).map(c=>`<option value="${esc(c.id)}" ${state.settings.defaultCalendar===c.id?'selected':''}>${esc(c.summary)}</option>`).join('')}</select></label>`:''}<p class="scratch-note">Google appointments are saved directly to your selected calendar. Refresh receives changes from elsewhere. Offline Google edits need reconnection; notebook appointments remain local until you move them to Google.</p></section><section class="settings-section"><h3>Backup & recovery</h3><p class="backup-status">Google backup: ${esc(Google.backupConnected()?cloudStatus:state.settings.googleClientId?'Reconnect to resume':'Setup required')}</p><p>Writing saves automatically to two stores on this device, with recent recovery copies. Connected Google backup saves a separate complete copy after changes, at most once a minute while the app is open. Export a file before clearing browser data. Updates keep your existing entries.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="secondary" data-action="cloud-backup" ${!Google.backupConnected()?'disabled':''}>Back up to Google now</button><button class="secondary" data-action="cloud-copies" ${!Google.backupConnected()?'disabled':''}>Google saved copies</button><button class="secondary" data-action="protect-storage">Protect device storage</button><button class="secondary" data-action="export-backup">Export notebook</button><button class="secondary" data-action="import-backup">Restore from file</button><button class="secondary" data-action="snapshots">Recent saved copies</button><button class="secondary" data-action="trash">Recently deleted</button><button class="secondary" data-action="export-ics">Export calendar (.ics)</button></div></section><section class="settings-section"><h3>Install on your iPad</h3><p>Open this planner in Safari, tap Share, then Add to Home Screen. It opens as its own app. After the first visit, notebook pages and your writing work offline.</p><p class="scratch-note">Unbound Days · First edition. Multi-device cloud sync, background notifications and advanced handwriting recognition are planned next.</p></section>`);}
async function refreshGoogle(){if(googleBusy)return;googleBusy=true;try{const initial=!state.googleCalendars.length;const calendars=await Google.listCalendars();state.googleCalendars=calendars;state.settings.selectedCalendars=state.settings.selectedCalendars.filter(id=>calendars.some(c=>c.id===id));if(!calendars.some(c=>c.id===state.settings.defaultCalendar))state.settings.defaultCalendar=calendars.find(c=>c.primary)?.id||calendars.find(c=>['owner','writer'].includes(c.accessRole))?.id||'primary';if(!state.settings.selectedCalendars.length){const primary=calendars.find(c=>c.primary)||calendars[0];if(primary){state.settings.selectedCalendars=[primary.id];state.settings.defaultCalendar=primary.id;}}const result=await Promise.all(state.settings.selectedCalendars.map(async c=>(await Google.listEvents(c,year())).map(e=>Google.fromGoogle(e,c))));state.cachedGoogle=result.flat();state.googleFetchedYear=year();state.googleUpdatedAt=new Date().toISOString();save();render();toast('Google Calendar refreshed.');}finally{googleBusy=false;}}
function download(filename,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function findEvent(eventId){return [...state.events,...state.cachedGoogle].find(e=>e.id===eventId);}
function removeItem(collection,item){snapshot();state.trash.unshift({id:id(),collection,item:structuredClone(item),time:new Date().toISOString()});state.trash=state.trash.slice(0,50);state[collection]=state[collection].filter(t=>t.id!==item.id);save();render();}
function confirmAction(title,message,action){openModal(title,`<p>${esc(message)}</p><div class="modal-footer"><button class="secondary" data-action="close-modal">Cancel</button><button class="primary" id="confirm-action">Confirm</button></div>`);document.querySelector('#confirm-action').onclick=async()=>{const b=document.querySelector('#confirm-action');b.disabled=true;try{await action();closeModal();}catch(e){toast(e.message);b.disabled=false;}};}
function navigate(n){const d=parseDate(date);if(section==='calendar'&&view==='day')date=addDays(date,n);else if(section==='calendar'&&view==='week')date=addDays(date,n*7);else if(section==='goals'||section==='calendar'&&view==='year'){d.setFullYear(d.getFullYear()+n);date=dateKey(d);}else{d.setDate(1);d.setMonth(d.getMonth()+n);date=dateKey(d);}render();if(Google.connected()&&state.googleFetchedYear!==year())refreshGoogle().catch(e=>toast(e.message));}
function search(){openModal('Find a page or plan',`<input class="search-input" id="search-input" placeholder="Search your notebook…" aria-label="Search your notebook" autofocus><div id="search-results"><p style="margin-top:15px">Search appointments, tasks, goals and written notes.</p></div>`);document.querySelector('#search-input').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q)return;const results=[];[...state.events,...state.cachedGoogle].forEach(e=>{if(`${e.title} ${e.notes} ${e.location}`.toLowerCase().includes(q))results.push({type:'event',id:e.id,label:e.title,date:e.date});});state.tasks.forEach(t=>{if(`${t.title} ${t.notes} ${t.goal}`.toLowerCase().includes(q))results.push({type:'task',id:t.id,label:t.title,date:t.date});});state.notes.forEach(n=>{if(n.title.toLowerCase().includes(q))results.push({type:'note',id:n.id,label:n.title,date:''});});Object.entries(state.entries).forEach(([k,v])=>{if(v.toLowerCase().includes(q))results.push({type:'entry',id:k,label:v.slice(0,100),date:k.split(':')[1]});});document.querySelector('#search-results').innerHTML=results.slice(0,50).map(r=>`<button class="search-result" data-result-type="${r.type}" data-result-id="${esc(r.id)}"><strong>${esc(r.label)}</strong><small>${esc(r.type==='entry'?'Page':r.type)}${r.date&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)?' · '+formatDate(r.date,{day:'numeric',month:'short',year:'numeric'}):''}</small></button>`).join('')||'<p style="margin-top:15px">No matches yet.</p>';};}
function startDictation(button){const focused=focusField;if(!focused||!focused.isConnected){toast('Tap a writing field first, then Dictate. You can also use your keyboard microphone.');return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Use the microphone on your device keyboard to dictate into this field.');focused.focus();return;}if(speech){speech.stop();return;}const before=focused.value;speech=new Recognition();speech.lang='en-GB';speech.continuous=false;speech.interimResults=true;button?.classList.add('recording');speech.onresult=e=>{const text=Array.from(e.results).map(r=>r[0].transcript).join(' ');focused.value=before+(before&&!before.endsWith(' ')?' ':'')+text;focused.dispatchEvent(new Event('input',{bubbles:true}));};speech.onerror=e=>toast(e.error==='not-allowed'?'Microphone permission is needed for dictation.':'Dictation stopped. Your text has been kept.');speech.onend=()=>{button?.classList.remove('recording');speech=null;};try{speech.start();}catch(e){speech=null;toast(e.message);}}
let inkTool='pen',inkUndo=[],inkPaths=[],inkDrawing=null,inkContext=null,inkCanvas=null;
function setupInk(){inkCanvas=document.querySelector('#ink-canvas');if(!inkCanvas)return;inkPaths=structuredClone(state.ink[noteId]||[]);inkUndo=[];inkTool='pen';const resize=()=>{if(!inkCanvas.isConnected)return;const bounds=inkCanvas.getBoundingClientRect();if(!bounds.width)return;const scale=devicePixelRatio||1;inkCanvas.width=Math.round(bounds.width*scale);inkCanvas.height=Math.round(bounds.height*scale);inkContext=inkCanvas.getContext('2d');inkContext.setTransform(scale,0,0,scale,0,0);drawInk();};new ResizeObserver(resize).observe(inkCanvas);resize();const point=e=>{const r=inkCanvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height,p:e.pressure||.5};};inkCanvas.onpointerdown=e=>{if(e.pointerType==='touch')return;inkCanvas.setPointerCapture(e.pointerId);inkUndo.push(structuredClone(inkPaths));inkDrawing={tool:inkTool,color:state.settings.ink,points:[point(e)]};inkPaths.push(inkDrawing);drawInk();};inkCanvas.onpointermove=e=>{if(!inkDrawing)return;inkDrawing.points.push(point(e));drawInk();};inkCanvas.onpointerup=inkCanvas.onpointercancel=()=>{if(inkDrawing){inkDrawing=null;state.ink[noteId]=inkPaths;save();}};}
function drawInk(){if(!inkContext||!inkCanvas)return;const {width,height}=inkCanvas.getBoundingClientRect();inkContext.clearRect(0,0,width,height);for(const path of inkPaths){inkContext.globalCompositeOperation=path.tool==='eraser'?'destination-out':'source-over';inkContext.strokeStyle=path.color;inkContext.lineCap='round';inkContext.lineJoin='round';const ps=path.points;for(let i=0;i<ps.length;i++){const a=ps[Math.max(0,i-1)],b=ps[i];inkContext.lineWidth=path.tool==='eraser'?22:1.5+b.p*2.5;inkContext.beginPath();inkContext.moveTo(a.x*width,a.y*height);inkContext.lineTo(b.x*width+.01,b.y*height+.01);inkContext.stroke();}}inkContext.globalCompositeOperation='source-over';}

document.addEventListener('focusin',e=>{if(e.target.matches('textarea,input[type=text],input:not([type])'))focusField=e.target;});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.entry)setEntry(el.dataset.entry,el.value);if(el.dataset.noteTitle){const n=state.notes.find(n=>n.id===el.dataset.noteTitle);n.title=el.value;save();const b=document.querySelector(`[data-note="${n.id}"]`);if(b)b.textContent=n.title||'Untitled page';}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='year-select'){const d=parseDate(date);d.setDate(1);d.setFullYear(Number(el.value));date=dateKey(d);render();if(Google.connected())try{await refreshGoogle();}catch(err){toast(err.message);}}if(el.dataset.taskCheck){const t=state.tasks.find(t=>t.id===el.dataset.taskCheck);t.done=el.checked;save();render();}if(el.id==='favorites-only'){onlyFavorites=el.checked;gallery();}if(el.dataset.calendarToggle){const c=el.dataset.calendarToggle;state.settings.selectedCalendars=el.checked?[...state.settings.selectedCalendars,c]:state.settings.selectedCalendars.filter(x=>x!==c);save();if(Google.connected())try{await refreshGoogle();settings();}catch(err){toast(err.message);}}if(el.id==='default-calendar'){state.settings.defaultCalendar=el.value;save();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-day-cell]')){e.preventDefault();date=e.target.dataset.dayCell;view='day';render();}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();search();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-day-cell]');if(!b)return;const data=b.dataset;try{
if(data.section){closed=false;section=data.section;render();return;}if(data.view){view=data.view;render();return;}if(data.month!==undefined){date=`${year()}-${pad(Number(data.month)+1)}-01`;if(section==='calendar')view='month';closed=false;render();return;}if(data.date){date=data.date;section='calendar';view='day';render();return;}if(data.week){date=data.week;view='week';render();return;}if(data.dayCell){date=data.dayCell;view='day';render();return;}
if(data.editEvent){eventForm(data.editEvent);return;}if(data.editTask){taskForm(data.editTask);return;}if(data.moveTask){const t=state.tasks.find(t=>t.id===data.moveTask);openModal('Move task',`<p>${esc(t.title)}</p><form id="move-form" data-id="${t.id}"><label class="check-label">New date<input name="date" type="date" value="${addDays(t.date||TODAY,1)}" required></label><div class="modal-footer"><button class="primary" type="submit">Move task</button></div></form>`);return;}
if(data.goalTask!==undefined){const i=Number(data.goalTask);taskForm(null,entry(`goals:${year()}:${i}`).split('\n')[0]);document.querySelector('[name=goal]').value=`${months[i]} ${year()}`;document.querySelector('#task-form [name=date]').value=`${year()}-${pad(i+1)}-01`;return;}
if(data.note){noteId=data.note;render();return;}if(data.cover!==undefined){state.settings.cover=data.cover==='custom'?'custom':Number(data.cover);save();render();gallery();return;}if(data.fav!==undefined){const i=Number(data.fav);state.settings.favorites=state.settings.favorites.includes(i)?state.settings.favorites.filter(x=>x!==i):[...state.settings.favorites,i];save();gallery();return;}
if(data.habit){const h=state.habits.find(h=>h.id===data.habit),d=data.habitDate;h.checks=h.checks.includes(d)?h.checks.filter(x=>x!==d):[...h.checks,d];save();render();return;}if(data.editHabit){const h=state.habits.find(h=>h.id===data.editHabit);habitForm(h);return;}
if(data.inkTool){inkTool=data.inkTool;document.querySelectorAll('[data-ink-tool]').forEach(x=>x.classList.toggle('active',x.dataset.inkTool===inkTool));return;}
if(data.deleteNote){const n=state.notes.find(n=>n.id===data.deleteNote);confirmAction('Delete this page?', 'The page and its writing will be kept in Recently deleted.',()=>{removeItem('notes',n);noteId=state.notes[0]?.id||null;render();});return;}
if(data.deleteTask){const t=state.tasks.find(t=>t.id===data.deleteTask);confirmAction('Delete task?',t.title,()=>removeItem('tasks',t));return;}
if(data.deleteHabit){const h=state.habits.find(h=>h.id===data.deleteHabit);confirmAction('Delete habit?',h.title,()=>removeItem('habits',h));return;}
if(data.deleteEvent){const item=findEvent(data.deleteEvent);confirmAction('Delete appointment?',item.google?'This will delete the appointment in Google Calendar. Google deletions cannot be restored here.':item.repeat&&item.repeat!=='none'?'This deletes the whole repeating series. You can recover it in Recently deleted.':item.title,async()=>{if(item.google){await Google.deleteEvent(item);state.cachedGoogle=state.cachedGoogle.filter(x=>x.id!==item.id);save();render();}else removeItem('events',item);});return;}
if(data.restoreTrash){const index=state.trash.findIndex(t=>t.id===data.restoreTrash),t=state.trash[index];if(!state[t.collection].some(x=>x.id===t.item.id))state[t.collection].push(t.item);state.trash.splice(index,1);save();render();showTrash();return;}
if(data.snapshot!==undefined){const records=JSON.parse(localStorage.getItem(HISTORY)||'[]'),s=records[Number(data.snapshot)];confirmAction('Restore saved copy?',`Replace this notebook with the copy saved ${new Date(s.time).toLocaleString('en-GB')}? Export your current notebook first if you need to keep it.`,()=>{snapshot();state=s.data;storageCorrupt=false;save();render();});return;}
if(data.resultType){const k=data.resultId;closeModal();closed=false;if(data.resultType==='event'){const event=findEvent(k);date=event.date;section='calendar';view='day';render();eventForm(k);}else if(data.resultType==='task'){section='tasks';render();taskForm(k);}else if(data.resultType==='note'){section='notes';noteId=k;render();}else{const parts=k.split(':');if(parts[0]==='note'){section='notes';noteId=parts[1];}else if(parts[0]==='goals'){section='goals';date=`${parts[1]}-${pad((/^\d+$/.test(parts[2]||'')?Number(parts[2]):0)+1)}-01`;}else if(parts[0]==='day'){section='calendar';view='day';date=parts[1];}else if(parts[0]==='week'){section='calendar';view='week';date=parts[1];}else if(parts[0]==='reflection'){section='reflection';date=`${parts[1]}-${pad(Number(parts[2])+1)}-01`;}else if(parts[0]==='habits'){section='habits';date=parts[1]+'-01';}else if(parts[0]==='year'){section='calendar';view='year';date=parts[1]+'-01-01';}else{section='calendar';view='month';date=`${parts[1]}-${pad(Number(parts[2])+1)}-01`;}render();}return;}
if(data.cloudCopy){const restored=await Google.readBackup(data.cloudCopy);validateBackup(restored);confirmAction('Restore Google notebook?', 'This replaces the current notebook. Export a file first to keep a separate copy. A local recovery copy will also be kept.',()=>{snapshot();state=restored;storageCorrupt=false;noteId=state.notes[0]?.id||null;save();render();});return;}
switch(data.action){case 'cloud-backup':await runCloudBackup(true);settings();break;case 'cloud-copies':await cloudCopies();break;case 'protect-storage':toast(await navigator.storage?.persist?.()?'Device storage protection enabled. Keep Google or file backups too.':'This browser manages storage protection automatically. Keep Google or file backups.');break;case 'open':closed=false;render();break;case 'cover':closed=true;render();break;case 'close-modal':closeModal();break;case 'today':date=TODAY;closed=false;section='calendar';view='day';render();break;case 'prev':navigate(-1);break;case 'next':navigate(1);break;case 'add-event':eventForm();break;case 'add-task':taskForm();break;case 'gallery':gallery();break;case 'personalize':personalize();break;case 'settings':settings();break;case 'search':search();break;case 'dictate':startDictation(b);break;case 'pencil':document.body.classList.toggle('pencil-mode');toast('Write into a text field with iPad Scribble. Your writing becomes handwriting-font text.');focusField?.focus();break;case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Add to Home Screen in Safari for an app-style full screen.');break;case 'add-note':{const n={id:id(),title:'Untitled page',createdAt:new Date().toISOString()};state.notes.push(n);noteId=n.id;save();render();document.querySelector('[data-note-title]')?.focus();break;}case 'add-habit':habitForm();break;case 'carry-tasks':{const overdue=state.tasks.filter(t=>t.date&&t.date<TODAY&&!t.done);confirmAction('Move unfinished tasks?',`Move ${overdue.length} tasks to today?`,()=>{overdue.forEach(t=>t.date=TODAY);save();render();});break;}case 'upload-cover':document.querySelector('#cover-file').click();break;case 'undo-ink':if(inkUndo.length){inkPaths=inkUndo.pop();state.ink[noteId]=inkPaths;save();drawInk();}break;case 'clear-ink':confirmAction('Clear pen strokes?','Typed notes will be kept. Ink can be recovered from a recent saved copy.',()=>{snapshot();inkPaths=[];state.ink[noteId]=[];save();drawInk();});break;case 'export-backup':download(`Unbound-Days-${dateKey(new Date())}.json`,JSON.stringify(state,null,2),'application/json');break;case 'import-backup':document.querySelector('#backup-file').click();break;case 'export-ics':download('Unbound-Days.ics',toICS(state.events),'text/calendar');break;case 'snapshots':showSnapshots();break;case 'trash':showTrash();break;case 'google-connect':{const input=document.querySelector('#google-client');state.settings.googleClientId=input.value.trim();save();b.disabled=true;try{await Google.connect(state.settings.googleClientId,document.querySelector('#google-backup').checked);await refreshGoogle();if(Google.backupConnected())await runCloudBackup(true);settings();}catch(err){document.querySelector('#google-error').textContent=err.message;b.disabled=false;}break;}case 'google-refresh':b.disabled=true;try{await refreshGoogle();settings();}catch(err){document.querySelector('#google-error').textContent=err.message;b.disabled=false;}break;case 'google-disconnect':Google.disconnect();state.cachedGoogle=[];state.googleCalendars=[];state.settings.selectedCalendars=[];save();render();settings();break;}
}catch(err){toast(err.message);}});
function habitForm(h=null){openModal(h?'Edit habit':'New habit',`<form id="habit-form" data-id="${h?.id||''}"><div class="form-grid"><label class="wide">Habit<input type="text" name="title" value="${esc(h?.title||'')}" required maxlength="100" autofocus></label></div><div class="modal-footer">${h?`<button type="button" class="secondary danger" data-delete-habit="${h.id}">Delete</button>`:''}<button class="primary" type="submit">Save habit</button></div></form>`);}
function showTrash(){openModal('Recently deleted',state.trash.map(t=>`<div class="trash-item"><span>${esc(t.item.title)}</span><button class="secondary" data-restore-trash="${t.id}">Restore</button></div>`).join('')||'<p>No deleted entries.</p>');}
function showSnapshots(){const records=JSON.parse(localStorage.getItem(HISTORY)||'[]');openModal('Recent saved copies',`<p>Up to five copies are kept locally. Exported backups are safer if browser data is cleared.</p><div class="backup-list">${records.map((r,i)=>`<button data-snapshot="${i}">${new Date(r.time).toLocaleString('en-GB')} · ${r.data.events.length} events · ${r.data.tasks.length} tasks</button>`).join('')||'<p>No saved copies yet.</p>'}</div>`);}
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form)),itemId=form.dataset.id;try{
if(form.id==='event-form'){const old=findEvent(itemId);if(data.endDate<data.date)throw Error('End date must be on or after the start date.');if(data.time&&!data.endTime)throw Error('Add an end time for this appointment.');if(data.time&&new Date(`${data.endDate}T${data.endTime}`)<=new Date(`${data.date}T${data.time}`))throw Error('End time must be after the start time.');const event={...old,...data,id:itemId||id(),title:data.title.trim(),lastDate:data.time&&data.endTime==='00:00'?addDays(data.endDate,-1):data.endDate,repeat:old?.google?'none':data.repeat||'none'};if(!event.title)throw Error('Add an appointment title.');const destination=old?.google?.calendar||data.destination;const submit=form.querySelector('[type=submit]');submit.disabled=true;try{if(destination!=='local'){const result=await Google.saveEvent(event,destination);const converted=Google.fromGoogle(result,destination);state.cachedGoogle=state.cachedGoogle.filter(x=>x.id!==converted.id);state.cachedGoogle.push(converted);if(old&&!old.google)state.events=state.events.filter(x=>x.id!==old.id);if(!state.settings.selectedCalendars.includes(destination))state.settings.selectedCalendars.push(destination);}else{const i=state.events.findIndex(x=>x.id===itemId);if(i<0)state.events.push(event);else state.events[i]=event;}save();date=data.date;render();closeModal();toast('Appointment saved.');}finally{submit.disabled=false;}}
if(form.id==='task-form'){const title=data.title.trim();if(!title)throw Error('Add a task title.');const t={...data,id:itemId||id(),title,done:state.tasks.find(t=>t.id===itemId)?.done||false};const i=state.tasks.findIndex(t=>t.id===itemId);if(i<0)state.tasks.push(t);else state.tasks[i]=t;save();render();closeModal();}
if(form.id==='move-form'){state.tasks.find(t=>t.id===itemId).date=data.date;save();render();closeModal();toast('Task moved.');}
if(form.id==='personalize-form'){Object.assign(state.settings,data);save();render();closeModal();}
if(form.id==='habit-form'){if(!data.title.trim())throw Error('Give this habit a name.');if(itemId)state.habits.find(h=>h.id===itemId).title=data.title.trim();else state.habits.push({id:id(),title:data.title.trim(),checks:[]});save();render();closeModal();}
if(form.id==='upload-form'){state.settings.customCover=form.dataset.image;state.settings.cover='custom';state.settings.coverPosition=Number(data.position);state.settings.coverInk=data.coverInk;save();render();closeModal();toast('Your cover is ready.');}
}catch(err){const error=form.querySelector('#form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.querySelector('#cover-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>8*1024*1024){toast('Choose an image smaller than 8 MB.');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPEG, PNG or WebP image.');return;}try{const image=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,1400/image.width);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const imageUrl=canvas.toDataURL('image/jpeg',.82);image.close();openModal('Your own cover',`<form id="upload-form" data-image="${imageUrl}"><div class="upload-preview" style="background-image:url('${imageUrl}')"></div><label class="check-label">Crop position<input name="position" type="range" min="0" max="100" value="50" aria-label="Cover crop position"></label><label class="check-label">Lettering<select name="coverInk"><option value="#fff9ec">Ivory</option><option value="#273238">Charcoal</option><option value="#e4c18c">Warm gold</option></select></label><div class="modal-footer"><button class="primary" type="submit">Use this cover</button></div></form>`);document.querySelector('[name=position]').oninput=e=>document.querySelector('.upload-preview').style.backgroundPosition=e.target.value+'% center';}catch{toast('That image could not be opened. Try a JPEG or PNG.');}});
document.querySelector('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>15*1024*1024)throw Error('Backup is too large.');const parsed=JSON.parse(await file.text());validateBackup(parsed);confirmAction('Restore notebook?', 'This replaces the current notebook. A local saved copy will be kept, but export your current notebook first if you need it.',()=>{snapshot();state=parsed;storageCorrupt=false;noteId=state.notes[0]?.id||null;save();render();toast('Notebook restored.');});}catch(err){toast('Could not restore: '+err.message);}});
function validateBackup(data){if(data.version!==1)throw Error('Unsupported backup format.');for(const key of ['events','tasks','notes','habits','trash','cachedGoogle','googleCalendars'])if(!Array.isArray(data[key]))throw Error(`Missing ${key}.`);if(!data.entries||typeof data.entries!=='object'||Array.isArray(data.entries)||!data.settings||!data.ink)throw Error('Invalid notebook data.');for(const e of [...data.events,...data.cachedGoogle])if(typeof e.id!=='string'||typeof e.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date))throw Error('Invalid appointment.');for(const t of data.tasks)if(typeof t.id!=='string'||typeof t.title!=='string')throw Error('Invalid task.');for(const n of data.notes)if(typeof n.id!=='string'||typeof n.title!=='string')throw Error('Invalid note.');for(const h of data.habits)if(typeof h.title!=='string'||!Array.isArray(h.checks))throw Error('Invalid habit.');for(const value of Object.values(data.entries))if(typeof value!=='string')throw Error('Invalid writing.');if(!Array.isArray(data.settings.favorites)||!Array.isArray(data.settings.selectedCalendars))throw Error('Invalid preferences.');if(data.settings.customCover&&!/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(data.settings.customCover))throw Error('Invalid cover image.');if(!/^#[0-9a-fA-F]{6}$/.test(data.settings.ink)||data.settings.coverInk&&!/^#[0-9a-fA-F]{6}$/.test(data.settings.coverInk))throw Error('Invalid ink colour.');if(![...Array(coverNames.length).keys(),'custom'].includes(data.settings.cover))throw Error('Invalid cover.');data.settings.font='Caveat';}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const reminded=new Set();function checkReminders(){const now=new Date();state.events.filter(e=>e.time&&e.reminder!==''&&e.reminder!=null&&eventOnDate(e,dateKey(now))).forEach(e=>{const start=new Date(`${dateKey(now)}T${e.time}`),due=start-Number(e.reminder)*60000,key=e.id+dateKey(now);if(now>=due&&now-due<60000&&!reminded.has(key)){reminded.add(key);toast(`Reminder: ${e.title} at ${e.time}`);}});}setInterval(checkReminders,30000);
window.addEventListener('online',()=>toast('You’re back online. Refresh Google Calendar in Settings.'));
window.addEventListener('storage',e=>{if(e.key===KEY){externalChange=true;document.querySelector('#save-status').textContent='Another tab updated this notebook';toast('Another tab updated this notebook. Reload before editing to keep both copies safe.');}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&cloudDirty&&Google.backupConnected())runCloudBackup(true).catch(()=>{});});
render();if(storageError)document.querySelector('#save-status').textContent='Recovery needed · restore a backup';if(storageError)toast('Saved notebook could not be read. Restore a backup before adding new entries.');
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
